        "sending",
        "streaming",
        "waiting_for_user",
        "failed",
        "missing",
        "dispatch",
    ] {
        let c = client();
        let f = fence(&c);
        let s = store("");
        if cause == "missing" {
            s.borrow_mut().rows.remove("physical_a");
        } else if cause != "dispatch" {
            s.borrow_mut().rows.get_mut("physical_a").unwrap()["status"] = json!(cause);
        }
